"""Parsing and aggregation of plain-text ledgers."""

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}")
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?")


class ParseError(ValueError):
    """A line of the ledger is invalid. ``line`` is its 1-based number."""

    def __init__(self, line, reason):
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def _parse_line(text, number):
    fields = re.split(r"[ \t]+", text.strip(), maxsplit=3)
    if len(fields) < 3:
        raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE]")
    date_s, category, amount_s = fields[:3]
    note = fields[3] if len(fields) > 3 else ""
    if not _DATE_RE.fullmatch(date_s):
        raise ParseError(number, "invalid date %r (expected YYYY-MM-DD)" % date_s)
    try:
        date = datetime.date(int(date_s[:4]), int(date_s[5:7]), int(date_s[8:10]))
    except ValueError:
        raise ParseError(number, "date %r does not exist" % date_s) from None
    if not _AMOUNT_RE.fullmatch(amount_s):
        raise ParseError(number, "invalid amount %r" % amount_s)
    return Entry(date, category.lower(), Decimal(amount_s), note)


def parse(text):
    """Parse ledger text into a list of Entry, in file order."""
    entries = []
    for number, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        entries.append(_parse_line(line, number))
    return entries


def balance(entries):
    return sum((e.amount for e in entries), Decimal("0"))


def by_category(entries):
    totals = {}
    for e in entries:
        totals[e.category] = totals.get(e.category, Decimal("0")) + e.amount
    return totals


def by_month(entries):
    totals = {}
    for e in entries:
        key = "%04d-%02d" % (e.date.year, e.date.month)
        totals[key] = totals.get(key, Decimal("0")) + e.amount
    return totals


def filter_entries(entries, category=None, since=None, until=None):
    wanted = category.lower() if category is not None else None
    result = []
    for e in entries:
        if wanted is not None and e.category != wanted:
            continue
        if since is not None and e.date < since:
            continue
        if until is not None and e.date > until:
            continue
        result.append(e)
    return result
