import argparse
import csv
import datetime
import io
import json
import os
import re
import sys
from decimal import Decimal

from . import ledger

_TWO = Decimal("0.01")


def money(amount):
    text = str(amount.quantize(_TWO))
    return "0.00" if text == "-0.00" else text


def _format_entry(e):
    line = "%s %s %s" % (e.date.isoformat(), e.category, money(e.amount))
    return line + " " + e.note if e.note else line


def _date_arg(value):
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
        raise argparse.ArgumentTypeError("invalid date %r (expected YYYY-MM-DD)" % value)
    try:
        return datetime.date(int(value[:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        raise argparse.ArgumentTypeError("date %r does not exist" % value) from None


class _Parser(argparse.ArgumentParser):
    def __init__(self, *args, **kwargs):
        kwargs.setdefault("prog", "pennywise")
        super().__init__(*args, **kwargs)


def _build_parser():
    p = _Parser(description="Read a plain-text household ledger.")
    sub = p.add_subparsers(dest="command", parser_class=_Parser, metavar="COMMAND")
    sub.required = True

    s = sub.add_parser("balance", help="print the total")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--json", action="store_true")

    s = sub.add_parser("summary", help="totals per category or month")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--by", choices=["category", "month"], default="category")
    s.add_argument("--json", action="store_true")

    s = sub.add_parser("list", help="list entries, oldest first")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--category")
    s.add_argument("--since", type=_date_arg)
    s.add_argument("--until", type=_date_arg)
    s.add_argument("--json", action="store_true")

    s = sub.add_parser("add", help="append an entry")
    s.add_argument("file", metavar="FILE")
    s.add_argument("date", metavar="DATE")
    s.add_argument("category", metavar="CATEGORY")
    s.add_argument("amount", metavar="AMOUNT")
    s.add_argument("note", metavar="NOTE", nargs="?", default="")

    s = sub.add_parser("export", help="print entries as CSV")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--format", choices=["csv"], default="csv")
    return p


class _Fail(Exception):
    def __init__(self, message, code):
        super().__init__(message)
        self.code = code


def _read(path):
    if path == "-":
        try:
            return sys.stdin.read()
        except (OSError, UnicodeDecodeError, ValueError) as exc:
            raise _Fail("cannot read standard input: %s" % exc, 2)
    try:
        with open(path, encoding="utf-8", newline="") as fh:
            return fh.read()
    except (OSError, UnicodeDecodeError) as exc:
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else str(exc)
        raise _Fail("%s: %s" % (path, reason), 2)


def _sorted(entries):
    return sorted(entries, key=lambda e: e.date)


def _cmd_balance(args):
    total = money(ledger.balance(ledger.parse(_read(args.file))))
    return json.dumps({"balance": total}) + "\n" if args.json else total + "\n"


def _cmd_summary(args):
    entries = ledger.parse(_read(args.file))
    totals = ledger.by_category(entries) if args.by == "category" else ledger.by_month(entries)
    names = sorted(totals)
    if args.json:
        return json.dumps({n: money(totals[n]) for n in names}) + "\n"
    return "".join("%s  %s\n" % (n, money(totals[n])) for n in names)


def _cmd_list(args):
    entries = ledger.parse(_read(args.file))
    entries = _sorted(ledger.filter_entries(entries, args.category, args.since, args.until))
    if args.json:
        return json.dumps([
            {"date": e.date.isoformat(), "category": e.category,
             "amount": money(e.amount), "note": e.note}
            for e in entries
        ]) + "\n"
    return "".join(_format_entry(e) + "\n" for e in entries)


def _cmd_export(args):
    entries = _sorted(ledger.parse(_read(args.file)))
    out = io.StringIO()
    w = csv.writer(out, lineterminator="\n")
    w.writerow(["date", "category", "amount", "note"])
    for e in entries:
        w.writerow([e.date.isoformat(), e.category, money(e.amount), e.note])
    return out.getvalue()


def _cmd_add(args):
    if args.file == "-":
        raise _Fail("add cannot write to standard input", 2)
    for name, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not value or re.search(r"\s", value):
            raise _Fail("invalid %s %r: must be a single word" % (name, value), 1)
    if args.category.startswith("#"):
        raise _Fail("invalid category %r: must not start with '#'" % args.category, 1)
    if re.search(r"[\r\n\x0b\x0c\x1c\x1d\x1e\x85  ]", args.note):
        raise _Fail("invalid note: must not contain a line break", 1)
    line = "%s %s %s" % (args.date, args.category, args.amount)
    if args.note.strip():
        line += " " + args.note
    try:
        entries = ledger.parse(line)
    except ledger.ParseError as exc:
        raise _Fail(exc.reason, 1)
    if len(entries) != 1:
        raise _Fail("invalid entry", 1)
    text = _format_entry(entries[0])
    try:
        needs_newline = False
        if os.path.exists(args.file) and os.path.getsize(args.file) > 0:
            with open(args.file, "rb") as fh:
                fh.seek(-1, os.SEEK_END)
                needs_newline = fh.read(1) not in (b"\n", b"\r")
        with open(args.file, "a", encoding="utf-8", newline="") as fh:
            fh.write(("\n" if needs_newline else "") + text + "\n")
    except OSError as exc:
        raise _Fail("%s: %s" % (args.file, exc.strerror or exc), 2)
    return text + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def main(argv=None):
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        output = _COMMANDS[args.command](args)
    except ledger.ParseError as exc:
        sys.stderr.write("pennywise: %s\n" % exc)
        return 1
    except _Fail as exc:
        sys.stderr.write("pennywise: %s\n" % exc)
        return exc.code
    sys.stdout.write(output)
    return 0
